  <style>
    :root {
      color-scheme: dark;
      --bg: #090b10;
      --panel: rgba(18, 22, 31, 0.92);
      --panel-strong: #121722;
      --panel-soft: rgba(255, 255, 255, 0.04);
      --border: rgba(255, 255, 255, 0.09);
      --text: #f3f6fb;
      --muted: #99a3b8;
      --accent: #7c9cff;
      --danger: #ff5d73;
      --danger-strong: #ff4260;
      --shadow: 0 28px 70px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 20px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 32%),
        linear-gradient(160deg, #07090e 0%, #0d1118 48%, #080a0f 100%);
      color: var(--text);
    }

    .page {
      width: min(100%, 960px);
    }

    .card {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .media {
      position: relative;
      aspect-ratio: 16 / 10;
      background:
        linear-gradient(145deg, rgba(124, 156, 255, 0.18), rgba(255, 93, 115, 0.08)),
        url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=80") center/cover;
    }

    .media::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(9, 11, 16, 0.72), transparent 42%);
    }

    .badge {
      position: absolute;
      top: 18px;
      left: 18px;
      z-index: 1;
      padding: 8px 12px;
      border: 1px solid rgba(255, 255, 255, 0.16);
      border-radius: 999px;
      background: rgba(9, 11, 16, 0.5);
      color: #dbe5ff;
      font-size: 0.82rem;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .content {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 20px;
      padding: 24px;
    }

    .details h1 {
      margin: 0 0 8px;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .details p {
      margin: 0;
      max-width: 52ch;
      color: var(--muted);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 14px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 600;
      color: var(--text);
      cursor: pointer;
      transition: transform 140ms ease, background 140ms ease, box-shadow 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(124, 156, 255, 0.45);
      outline-offset: 2px;
    }

    .secondary {
      border: 1px solid var(--border);
      background: var(--panel-soft);
    }

    .trigger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      box-shadow: 0 14px 30px rgba(255, 66, 96, 0.28);
    }

    dialog {
      width: min(92vw, 430px);
      padding: 0;
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      color: var(--text);
      background: linear-gradient(180deg, rgba(22, 27, 39, 0.98), rgba(15, 19, 29, 0.98));
      box-shadow: 0 30px 80px rgba(0, 0, 0, 0.58);
    }

    dialog::backdrop {
      background: rgba(5, 7, 11, 0.7);
      backdrop-filter: blur(8px);
    }

    .modal-body {
      padding: 28px;
    }

    .modal-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 16px;
      background: rgba(255, 93, 115, 0.14);
      color: #ff97a7;
      font-size: 1.5rem;
    }

    .modal-body h2 {
      margin: 0 0 10px;
      font-size: 1.5rem;
    }

    .modal-body p {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .danger {
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
    }

    @media (max-width: 640px) {
      .content,
      .modal-actions {
        flex-direction: column;
      }

      .actions,
      .modal-actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="card" aria-label="Image preview">
      <div class="media">
        <div class="badge">Library Preview</div>
      </div>
      <div class="content">
        <div class="details">
          <h1>Coastal Horizon</h1>
          <p>
            A full-size preview of your selected image. Use the delete action below if you want to
            permanently remove it from your library.
          </p>
        </div>
        <div class="actions">
          <button type="button" class="secondary">Download</button>
          <button type="button" class="trigger">Delete image</button>
        </div>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title">
    <div class="modal-body">
      <div class="modal-icon" aria-hidden="true">!</div>
      <h2 id="delete-title">Delete this image?</h2>
      <p>
        This will remove <strong>Coastal Horizon</strong> from your library. This action cannot be
        undone.
      </p>
      <div class="modal-actions">
        <button type="button" class="secondary" id="cancel-button">Cancel</button>
        <button type="button" class="danger" id="confirm-button">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById("delete-dialog");
    const trigger = document.querySelector(".trigger");
    const cancelButton = document.getElementById("cancel-button");
    const confirmButton = document.getElementById("confirm-button");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    cancelButton.addEventListener("click", () => {
      dialog.close();
    });

    confirmButton.addEventListener("click", () => {
      dialog.close();
    });
  </script>
</body>
</html>
